extern "C" {
void cn_combat_scaling(const int* rows,int count,const int* multipliers,int mult_count,int* out){for(int k=0;k<count;++k){const int* r=rows+5*k;out[3*k]=scale_level(r[0],r[1],r[2],r[3],r[4]?multipliers:nullptr,mult_count);out[3*k+1]=crown_tower_damage(r[3],r[0]);out[3*k+2]=pack_level(r[1],r[3]);}}
void cn_combat_trig(const int* rows,int count,int* out){for(int k=0;k<count;++k){int x=rows[3*k],y=rows[3*k+1],a=rows[3*k+2];out[4*k]=combat_sine(a);out[4*k+1]=combat_angle(x,y);combat_rotate(x,y,a);out[4*k+2]=x;out[4*k+3]=y;}}
void cn_combat_damage(const int* rows,int count,int* out){for(int k=0;k<count;++k){const int* row=rows+k*8;CombatHealth h;h.hp=h.maximum=row[0];h.shield=row[1];DamageContext q;q.forbidden=row[4]&1;q.immune=row[4]&2;q.hidden=row[4]&4;q.untouchable=row[4]&8;q.held=row[4]&16;q.ended=row[4]&32;q.unkillable=row[4]&64;q.target_buffs=!(row[4]&128);q.attacker_buffs=!(row[4]&256);q.reduction_percent=row[5];q.attacker_percent=row[6];q.crown=row[7];q.attacker_crown_percent=30;auto r=damage_with_heading(h,row[2],row[3],17,-90,q);int* o=out+k*8;o[0]=h.hp;o[1]=h.shield;o[2]=r.amount;o[3]=r.landed;o[4]=r.died;o[5]=r.accepted;o[6]=h.last_hit_heading;auto again=apply_damage(h,row[2],row[3],0,0,q);o[7]=again.amount;(void)row[4];}}
void cn_combat_launch_flight(const int* row,int* output){ProjectileState p;ProjectileConfig c;c.speed=row[0];c.gravity=row[1];c.radius=0;c.damage=0;c.constant_height=row[2];launch_projectile(p,c,1,0,0,row[3],row[4],row[5],row[6],row[7]);p.delay_ms=row[8];struct World{int next_hit_id(){return 1;}CombatTarget* find_target(int){return nullptr;}int target_count(){return 0;}CombatTarget& target_at(int){static CombatTarget t;return t;}void queue_hit(CombatHit){}void apply_buff(int,int,int,int,int,int){}void push(int,int,int,int){}ProjectileChain& chain(int){static ProjectileChain c;return c;}void return_pending(int,int){}void fault(int){assert(false);}}w;
for(int k=0;k<row[9];++k){tick_projectile(p,c,w);int* o=output+k*5;o[0]=p.x;o[1]=p.y;o[2]=p.z;o[3]=p.delay_ms;o[4]=p.released;}}
void cn_combat_arrows(int seed,int radius,int projectile_radius,int count,int waves,int interval,int wave_interval,int* output){ProjectileState p[64];ProjectileChain chain[8];ProjectileConfig c;c.radius=projectile_radius;SpellProjectileConfig s;s.count=count;s.waves=waves;s.interval_ms=interval;s.wave_interval_ms=wave_interval;s.radius=radius;s.ring=true;BattleRandom r{seed};int n=cast_spell_projectiles(p,64,chain,8,0,s,c,100,0,9000,1000,750,14500,18000,0,0,r);for(int k=0;k<n;++k){int* o=output+k*8;o[0]=p[k].x;o[1]=p[k].y;o[2]=p[k].z;o[3]=p[k].aim_x;o[4]=p[k].aim_y;o[5]=p[k].ring_x;o[6]=p[k].ring_y;o[7]=p[k].delay_ms;}}
}
extern "C" void cn_combat_homing(const int* row,const int* path,int* output){ProjectileState p;ProjectileConfig c;c.speed=row[0];c.gravity=row[1];c.homing=true;launch_projectile(p,c,1,10,0,row[2],row[3],row[4],row[5],row[6]);struct World{CombatTarget t;int next_hit_id(){return 1;}CombatTarget* find_target(int id){return id==10?&t:nullptr;}int target_count(){return 1;}CombatTarget& target_at(int){return t;}void queue_hit(CombatHit){}void apply_buff(int,int,int,int,int,int){}void push(int,int,int,int){}ProjectileChain& chain(int){static ProjectileChain c;return c;}void return_pending(int,int){}void fault(int){assert(false);}}w;w.t.id=10;w.t.hp=1000;
for(int k=0;k<row[7];++k){w.t.x=path[k*3];w.t.y=path[k*3+1];w.t.z=path[k*3+2];tick_projectile(p,c,w);int* o=output+k*7;o[0]=p.x;o[1]=p.y;o[2]=p.z;o[3]=p.aim_x;o[4]=p.aim_y;o[5]=p.aim_z;o[6]=p.released;}}
